using Cosmos.Application.Abstractions.Persistence;using Cosmos.Contracts.Organization;using Cosmos.Persistence.Connection;using Dapper;
namespace Cosmos.Persistence.Repositories;
public sealed class CompanyBranchMasterRepository(ISqlConnectionFactory factory):ICompanyBranchMasterRepository { public async Task<IReadOnlyCollection<CompanyDto>> CompaniesAsync(string? s,bool a,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);return (await c.QueryAsync<CompanyDto>(new CommandDefinition("SELECT Id,Code,Name,IsActive FROM dbo.Companies WHERE IsDeleted=0 AND (@a=0 OR IsActive=1) AND (@s IS NULL OR Code LIKE '%'+@s+'%' OR Name LIKE '%'+@s+'%') ORDER BY Name",new{s,a},cancellationToken:ct))).AsList();} public async Task<CompanyDto?> CompanyAsync(long id,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);return await c.QuerySingleOrDefaultAsync<CompanyDto>(new CommandDefinition("SELECT Id,Code,Name,IsActive FROM dbo.Companies WHERE Id=@id AND IsDeleted=0",new{id},cancellationToken:ct));} public async Task<CompanyDto> SaveCompanyAsync(long? id,string code,string name,bool active,long? u,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);var sql=id is null?"INSERT dbo.Companies(Code,Name,IsActive,CreatedBy) OUTPUT INSERTED.Id,INSERTED.Code,INSERTED.Name,INSERTED.IsActive VALUES(@code,@name,@active,@u)":"UPDATE dbo.Companies SET Code=@code,Name=@name,IsActive=@active,UpdatedAtUtc=SYSUTCDATETIME(),UpdatedBy=@u OUTPUT INSERTED.Id,INSERTED.Code,INSERTED.Name,INSERTED.IsActive WHERE Id=@id AND IsDeleted=0";return await c.QuerySingleAsync<CompanyDto>(new CommandDefinition(sql,new{id,code,name,active,u},cancellationToken:ct));} public async Task<IReadOnlyCollection<BranchDto>> BranchesAsync(long? companyId,string? s,bool a,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);return (await c.QueryAsync<BranchDto>(new CommandDefinition("SELECT Id,CompanyId,Code,Name,IsActive FROM dbo.Branches WHERE IsDeleted=0 AND (@companyId IS NULL OR CompanyId=@companyId) AND (@a=0 OR IsActive=1) AND (@s IS NULL OR Code LIKE '%'+@s+'%' OR Name LIKE '%'+@s+'%') ORDER BY Name",new{companyId,s,a},cancellationToken:ct))).AsList();} public async Task<BranchDto?> BranchAsync(long id,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);return await c.QuerySingleOrDefaultAsync<BranchDto>(new CommandDefinition("SELECT Id,CompanyId,Code,Name,IsActive FROM dbo.Branches WHERE Id=@id AND IsDeleted=0",new{id},cancellationToken:ct));} public async Task<BranchDto> SaveBranchAsync(long? id,long companyId,string code,string name,bool active,long? u,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);var sql=id is null?"INSERT dbo.Branches(CompanyId,Code,Name,IsActive,CreatedBy) OUTPUT INSERTED.Id,INSERTED.CompanyId,INSERTED.Code,INSERTED.Name,INSERTED.IsActive VALUES(@companyId,@code,@name,@active,@u)":"UPDATE dbo.Branches SET Code=@code,Name=@name,IsActive=@active,UpdatedAtUtc=SYSUTCDATETIME(),UpdatedBy=@u OUTPUT INSERTED.Id,INSERTED.CompanyId,INSERTED.Code,INSERTED.Name,INSERTED.IsActive WHERE Id=@id AND CompanyId=@companyId AND IsDeleted=0";return await c.QuerySingleAsync<BranchDto>(new CommandDefinition(sql,new{id,companyId,code,name,active,u},cancellationToken:ct));}}
